#pragma once
#include "Common.h"

// One item (file/dir) inside an archive.
struct ArcItem {
  std::string name;          // path, '/' separated
  bool isDir = false;
  uint64_t size = 0;
  int64_t  packedSize = -1;  // -1 = show blank (solid non-first files)
  uint64_t mtimeFt = 0;      // FILETIME; hasMTime=false -> blank
  bool hasMTime = false;
  uint32_t attrib = 0;       // 7z style: (unix_mode << 16) | dos_bits
  bool hasAttrib = false;
  uint32_t crc = 0;
  bool hasCrc = false;
  bool encrypted = false;
  std::string method;        // "LZMA2:17", "Deflate", "Store", "" ...
  int block = -1;            // -1 -> blank in -slt
  // extra -slt lines appended after the standard ones, e.g. ("Host OS","Unix")
  std::vector<std::pair<std::string,std::string>> extra;
  // ---- internal use by reader ----
  uint32_t index = 0;        // index in archive item array
};

// Opened archive. Format implementations subclass this.
struct IArchive {
  virtual ~IArchive() {}
  std::string path;                       // disk path of archive file
  std::string type;                       // "7z" "zip" "tar" "gzip" "xz" "bzip2"
  std::vector<std::pair<std::string,std::string>> props; // header block lines (after Path/Type)
  std::vector<ArcItem> items;
  bool encryptedHeader = false;
  // Extract full data of item `index` (items[index]) into out.
  // password used when needed. Returns false + err on failure.
  virtual bool extract(uint32_t index, const std::string& password, ByteBuf& out, std::string& err) = 0;
};

// Open by signature detection. Returns nullptr + err when not a known archive.
IArchive* OpenArchive(const std::string& path, std::string& err);

// ---- writing ----
struct WriteEntry {
  std::string name;          // archive path ('/' separated)
  bool isDir = false;
  uint64_t mtimeFt = 0;      // FILETIME
  uint32_t attrib = 0;       // (unix_mode<<16)|dos
  bool hasMTime = true;
  bool hasAttrib = true;
  std::string diskPath;      // non-empty: read data from disk file
  ByteBuf memData;           // else: in-memory data
  uint32_t crc = 0;          // filled by writer if 0 and data available
  bool hasCrc = false;
};

struct WriteOptions {
  std::string format = "7z"; // "7z" "zip" "tar" "gzip" "xz" "bzip2"
  int level = 5;             // 0..9 (0 = store)
  bool solid = true;         // 7z
  std::string password;      // 7z (7zAES) / zip unsupported
  bool headerEncrypt = false;
  uint64_t dictSize = 0;     // 0 = auto
};

