#include "Common.h"
#include <cstdio>

bool ReadWholeFile(const std::string& path, ByteBuf& out) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) return false;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (n < 0) { fclose(f); return false; }
  out.resize((size_t)n);
  size_t r = n ? fread(out.data(), 1, (size_t)n, f) : 0;
  fclose(f);
  return r == (size_t)n;
}

bool WriteWholeFile(const std::string& path, const Byte* data, size_t size) {
  FILE* f = fopen(path.c_str(), "wb");
  if (!f) return false;
  size_t w = size ? fwrite(data, 1, size, f) : 0;
  bool ok = (w == size) && (fclose(f) == 0);
  return ok;
}

std::string FormatSizeKiB(uint64_t v) {
  char buf[64];
  uint64_t kib = (v + 512) / 1024;
  snprintf(buf, sizeof buf, "%llu bytes (%llu KiB)", (unsigned long long)v, (unsigned long long)kib);
  return buf;
}
